import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';
const root=path.resolve(process.argv[2]||'work/smartslider'),ready=JSON.parse(await readFile(path.join(root,'smartslider-ready.json'))),origin=ready.url;assert.equal(new URL(origin).hostname,'127.0.0.1');assert.equal(ready.authorized,true);
const browser=await chromium.launch({channel:'chrome'}),results=[];
try{for(const width of [1440,390]){
 const page=await browser.newPage({viewport:{width,height:900},hasTouch:width<600});page.setDefaultTimeout(15000);const blocked=[];
 await page.route('**/*',r=>{const u=new URL(r.request().url());if(u.origin===origin&&['GET','HEAD'].includes(r.request().method()))return r.continue();blocked.push(r.request().url());return r.abort();});
 assert.equal((await page.goto(origin+'/',{waitUntil:'networkidle'})).status(),200);const slider=page.locator('.n2-ss-slider').first();await slider.waitFor({state:'visible'});assert.equal(await slider.locator('.n2-ss-slide[data-slide-public-id]').count(),3);
 const active=()=>slider.locator('.n2-ss-slide-active').getAttribute('data-slide-public-id');const first=await active();assert.ok(first);
 await slider.screenshot({path:path.join(root,'source-slider-'+width+'-first.png')});const arrows=await slider.locator('.nextend-arrow-next').isVisible();const swipe=async(direction)=>{await slider.scrollIntoViewIfNeeded();const r=await slider.boundingBox(),cdp=await page.context().newCDPSession(page),start=r.x+r.width*(direction>0?.8:.2),end=r.x+r.width*(direction>0?.2:.8),y=r.y+r.height/2;await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:start,y}]});for(let i=1;i<=8;i++){await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:start+(end-start)*i/8,y}]});await page.waitForTimeout(25);}await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await cdp.detach();};if(arrows)await slider.locator('.nextend-arrow-next').click();else await swipe(1);await page.waitForFunction(first=>document.querySelector('.n2-ss-slide-active')?.getAttribute('data-slide-public-id')!==first,first);const second=await active();assert.notEqual(second,first);await page.waitForTimeout(900);await slider.screenshot({path:path.join(root,'source-slider-'+width+'-second.png')});
 if(arrows){await slider.locator('.nextend-arrow-previous').focus();await page.keyboard.press('Enter');}else await swipe(-1);await page.waitForFunction(first=>document.querySelector('.n2-ss-slide-active')?.getAttribute('data-slide-public-id')===first,first);
 assert.equal(await slider.evaluate(el=>{const r=el.getBoundingClientRect();return r.width>0&&r.left>=-1&&r.right<=innerWidth+1;}),true);assert.deepEqual(blocked,[]);results.push({width,slides:3,pointerNext:arrows,keyboardPrevious:arrows,touchBothDirections:!arrows,viewportFits:true});await page.close();
 }await writeFile(path.join(root,'source-check.json'),JSON.stringify({plugin:ready.plugins,results,externalDelivery:false},null,2));console.log(JSON.stringify(results));
}finally{await browser.close();}
